import SwiftUI
import Photos

struct BackupQueueView: View {
    @ObservedObject var backup: BackupEngine
    @ObservedObject var preferences: BackupPreferences
    @ObservedObject var analyzer: PhotoLibraryAnalyzer
    @ObservedObject var language: LanguageStore
    @StateObject private var smart = SmartCleanupAnalyzer()
    @State private var showMediaPicker = false
    @State private var showBackupReview = false
    @State private var showPostBackupCleanup = false
    @State private var deletingProtectedBatch = false
    @State private var cleanupError: String?
    @State private var smartMode = false
    @State private var showScreenshotDelete = false
    @State private var showStopConfirmation = false

    private var totalLibraryCount:Int{analyzer.photoCount+analyzer.videoCount}
    private var selectableCount:Int{smartMode ? smart.memoryCount:totalLibraryCount}
    private var requestedCount:Int{max(1,preferences.selectedCount(total:selectableCount))}
    private var estimatedBytes:Int64{guard totalLibraryCount>0 else{return 0};return Int64((Double(analyzer.estimatedBytes)/Double(totalLibraryCount))*Double(min(requestedCount,totalLibraryCount)))}
    private var estimatedSize:String{ByteCountFormatter.string(fromByteCount:estimatedBytes,countStyle:.file)}
    private var screenshotSize:String{smart.screenshotBytes==0 ? language.text("0 KB","0 Ko"):ByteCountFormatter.string(fromByteCount:smart.screenshotBytes,countStyle:.file)}
    private var orderLabel:String{preferences.backupOrder == .oldest ? language.text("Oldest first","Plus anciens d’abord"):language.text("Newest first","Plus récents d’abord")}
    private var protectedStillOnDevice:[PHAsset]{guard !backup.newlyProtectedLocalIdentifiers.isEmpty else{return []};let result=PHAsset.fetchAssets(withLocalIdentifiers:backup.newlyProtectedLocalIdentifiers,options:nil);var assets:[PHAsset]=[];result.enumerateObjects{asset,_,_ in assets.append(asset)};return assets}

    var body: some View {
        VStack(alignment:.leading,spacing:16){
            HStack{Label(language.text("Choose what to protect","Choisir quoi protéger"),systemImage:"checkmark.circle.fill").font(.headline);Spacer();if backup.queueTotal>0{Text("\(backup.queueCompleted+backup.queueFailed)/\(backup.queueTotal)").font(.subheadline.bold()).monospacedDigit()}}
            Text(language.text("You stay in control: choose specific photos and videos, or let Libérons separate memories from screenshots on your iPhone.","Vous gardez le contrôle : choisissez vos médias ou laissez Libérons séparer les souvenirs des captures d’écran sur votre iPhone.")).font(.subheadline).foregroundStyle(.secondary)
            Button{showMediaPicker=true}label:{Label(language.text("Choose photos and videos","Choisir les photos et vidéos"),systemImage:"photo.on.rectangle.angled").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.borderedProminent).controlSize(.large).disabled(backup.isRunning || !analyzer.canReadLibrary)
            Divider()
            VStack(alignment:.leading,spacing:12){
                HStack{Label(language.text("Smart cleanup","Nettoyage intelligent"),systemImage:"photo.stack").font(.headline);Spacer();if smart.isScanning{ProgressView().controlSize(.small)}}
                Text(language.text("Runs on this iPhone. Screenshots can be excluded from protection and cleaned separately.","Fonctionne sur cet iPhone. Les captures d’écran peuvent être exclues de la protection et nettoyées séparément.")).font(.caption).foregroundStyle(.secondary)
                if smart.memoryCount+smart.screenshotCount>0{
                    HStack(spacing:10){smartMetric(value:smart.memoryCount,label:language.text("Memories","Souvenirs"),icon:"photo.fill",tint:.blue);smartMetric(value:smart.screenshotCount,label:language.text("Screenshots","Captures"),icon:"rectangle.on.rectangle",tint:.orange)}
                    if smart.screenshotCount>0{Text(language.text("About \(screenshotSize) can be reviewed as screenshots.","Environ \(screenshotSize) peuvent être vérifiés comme captures d’écran.")).font(.caption).foregroundStyle(.secondary)}
                    Toggle(language.text("Protect memories only","Protéger seulement les souvenirs"),isOn:$smartMode).font(.subheadline.bold()).tint(.blue)
                    if smart.screenshotCount>0{Button(role:.destructive){showScreenshotDelete=true}label:{Label(language.text("Review & delete screenshots","Vérifier et supprimer les captures"),systemImage:"trash").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.bordered)}
                }
                Button{Task{await smart.scan()}}label:{Label(smart.memoryCount+smart.screenshotCount>0 ? language.text("Scan again","Analyser à nouveau"):language.text("Analyze my library","Analyser ma photothèque"),systemImage:"photo.on.rectangle").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.bordered).disabled(smart.isScanning || backup.isRunning || !analyzer.canReadLibrary)
            }
            if backup.queueTotal>0{
                ProgressView(value:backup.queueProgress).tint(backup.isPaused ? .orange:.blue)
                HStack(spacing:14){Label("\(backup.queueCompleted) "+language.text("protected","protégés"),systemImage:"checkmark.shield.fill").foregroundStyle(.green);if backup.queueFailed>0{Label("\(backup.queueFailed) "+language.text("failed","échoués"),systemImage:"exclamationmark.triangle.fill").foregroundStyle(.orange)}}.font(.caption.bold())
                if backup.isRunning{
                    HStack(spacing:10){
                        Button{backup.isPaused ? backup.resume():backup.pause()}label:{Label(backup.isPaused ? language.text("Resume","Reprendre"):language.text("Pause","Pause"),systemImage:backup.isPaused ? "play.fill":"pause.fill").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.borderedProminent).tint(backup.isPaused ? .green:.blue).disabled(backup.isStopping)
                        Button(role:.destructive){showStopConfirmation=true}label:{Label(language.text("Stop","Arrêter"),systemImage:"stop.fill").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.bordered).disabled(backup.isStopping)
                    }
                    Text(backup.isStopping ? language.text("Finishing active transfers safely. No new item will start.","Fin sécurisée des transferts actifs. Aucun nouvel élément ne démarrera.") : backup.isPaused ? language.text("Backup is paused. Tap Resume when you are ready.","La sauvegarde est en pause. Touchez Reprendre quand vous êtes prêt.") : language.text("\(backup.queuePercent)% complete · \(backup.queueRemaining) remaining","\(backup.queuePercent)% terminé · \(backup.queueRemaining) restants")).font(.caption).foregroundStyle(backup.isPaused ? .orange:.secondary)
                }
                if let name=backup.currentQueueFilename{Text(language.text("Now: ","En cours : ")+name).font(.caption).foregroundStyle(.secondary).lineLimit(1)}
            }
            if !backup.newlyProtectedLocalIdentifiers.isEmpty && !protectedStillOnDevice.isEmpty{Divider();VStack(alignment:.leading,spacing:10){Label(language.text("Already protected in Libérons","Déjà protégés dans Libérons"),systemImage:"checkmark.shield.fill").font(.subheadline.bold()).foregroundStyle(.green);Text(language.text("\(protectedStillOnDevice.count) protected item(s) are still in Apple Photos. You can keep them there or free the local space now.","\(protectedStillOnDevice.count) élément(s) protégé(s) sont encore dans Photos. Vous pouvez les garder ou libérer l’espace local maintenant.")).font(.caption).foregroundStyle(.secondary);Button(role:.destructive){showPostBackupCleanup=true}label:{Label(language.text("Remove protected originals from iPhone","Supprimer les originaux protégés de l’iPhone"),systemImage:"iphone.slash").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.bordered).disabled(deletingProtectedBatch);if let cleanupError{Text(cleanupError).font(.caption).foregroundStyle(.red)}}}
            Divider();Text(language.text("Automatic selection","Sélection automatique")).font(.caption.bold()).foregroundStyle(.secondary);Text("\(preferences.backupPercent)% · "+language.text("about \(requestedCount.formatted()) items","environ \(requestedCount.formatted()) éléments")).font(.subheadline.bold());if smartMode{Label(language.text("Screenshots excluded","Captures d’écran exclues"),systemImage:"checkmark.shield.fill").font(.caption.bold()).foregroundStyle(.green)};Text(language.text("Estimated \(estimatedSize). Choose which end of your library Libérons starts with.","Environ \(estimatedSize). Choisissez par quel côté de votre photothèque Libérons commence.")).font(.caption).foregroundStyle(.secondary)
            Picker(language.text("Order","Ordre"),selection:$preferences.backupOrder){Text(language.text("Oldest first","Anciens d’abord")).tag(BackupPreferences.BackupOrder.oldest);Text(language.text("Newest first","Récents d’abord")).tag(BackupPreferences.BackupOrder.newest)}.pickerStyle(.segmented)
            Button{showBackupReview=true}label:{Label(language.text("Continue","Continuer"),systemImage:"arrow.right.circle.fill").frame(maxWidth:.infinity).frame(height:34)}.buttonStyle(.bordered).controlSize(.large).disabled(backup.isRunning || !analyzer.canReadLibrary || selectableCount==0)
            Text(language.text("Nothing starts or deletes automatically. Libérons always shows a review first.","Rien ne démarre ni ne se supprime automatiquement. Libérons affiche toujours un récapitulatif d’abord.")).font(.caption).foregroundStyle(.secondary)
        }
        .padding(20).background(Color(uiColor:.systemBackground),in:RoundedRectangle(cornerRadius:28,style:.continuous)).shadow(color:.black.opacity(0.045),radius:18,y:7)
        .sheet(isPresented:$showMediaPicker){MediaSelectionView(backup:backup,language:language)}
        .sheet(isPresented:$showBackupReview){premiumBackupReview}
        .sheet(isPresented:$showScreenshotDelete){premiumScreenshotReview}
        .sheet(isPresented:$showPostBackupCleanup){premiumProtectedCleanupReview}
        .confirmationDialog(language.text("Stop this backup?","Arrêter cette sauvegarde ?"),isPresented:$showStopConfirmation,titleVisibility:.visible){Button(language.text("Stop backup","Arrêter la sauvegarde"),role:.destructive){backup.stop()};Button(language.text("Keep backing up","Continuer la sauvegarde"),role:.cancel){}}message:{Text(language.text("Items already protected stay protected. Active transfers finish safely, then Libérons stops without starting new items.","Les éléments déjà protégés restent protégés. Les transferts actifs se terminent en sécurité, puis Libérons s’arrête sans démarrer de nouveaux éléments."))}
        .onChange(of:backup.protectionBatchID){_,_ in if !backup.newlyProtectedLocalIdentifiers.isEmpty{showPostBackupCleanup=true}}
    }

    private var premiumBackupReview: some View { NavigationStack{VStack(alignment:.leading,spacing:22){Image(systemName:"icloud.and.arrow.up.fill").font(.system(size:44)).foregroundStyle(.blue);Text(language.text("Confirm protection","Confirmer la protection")).font(.largeTitle.bold());Text(language.text("Nothing has started yet. Check exactly what Libérons will protect before confirming.","Rien n’a encore commencé. Vérifiez exactement ce que Libérons va protéger avant de confirmer.")).foregroundStyle(.secondary);VStack(spacing:0){reviewRow(language.text("Selected percentage","Pourcentage choisi"),"\(preferences.backupPercent)%");Divider();reviewRow(language.text("Estimated items","Éléments estimés"),requestedCount.formatted());Divider();reviewRow(language.text("Estimated size","Taille estimée"),estimatedSize);Divider();reviewRow(language.text("Screenshots","Captures d’écran"),smartMode ? language.text("Excluded","Exclues"):language.text("Included","Incluses"));Divider();reviewRow(language.text("Order","Ordre"),orderLabel)}.padding(.horizontal,18).background(Color(uiColor:.secondarySystemGroupedBackground),in:RoundedRectangle(cornerRadius:20));Label(language.text("This starts cloud protection only. Nothing is removed from Apple Photos.","Cette confirmation démarre uniquement la protection dans le cloud. Rien n’est supprimé de Photos."),systemImage:"lock.shield.fill").font(.footnote).foregroundStyle(.secondary);Spacer();Button{showBackupReview=false;Task{if smartMode{await backup.backupMemories(localIdentifiers:smart.memoryIDs,count:requestedCount,newestFirst:preferences.backupOrder == .newest)}else{await backup.backupItems(count:requestedCount,newestFirst:preferences.backupOrder == .newest)}}}label:{Label(language.text("Confirm and start","Confirmer et commencer"),systemImage:"checkmark.shield.fill").fontWeight(.bold).frame(maxWidth:.infinity).frame(height:48)}.buttonStyle(.borderedProminent).disabled(backup.isRunning);Button(language.text("Cancel","Annuler")){showBackupReview=false}.frame(maxWidth:.infinity)}.padding(24).navigationTitle(language.text("Review","Récapitulatif")).navigationBarTitleDisplayMode(.inline)}}

    private var premiumScreenshotReview: some View { NavigationStack{VStack(alignment:.leading,spacing:22){Image(systemName:"rectangle.on.rectangle.slash").font(.system(size:44)).foregroundStyle(.red);Text(language.text("Delete screenshots?","Supprimer les captures d’écran ?")).font(.largeTitle.bold());Text(language.text("Libérons selected only items identified by Apple Photos as screenshots. Review the selection before asking Photos to remove them.","Libérons a sélectionné uniquement les éléments identifiés par Photos comme captures d’écran. Vérifiez la sélection avant de demander leur suppression à Photos.")).foregroundStyle(.secondary);VStack(spacing:0){reviewRow(language.text("Screenshots","Captures d’écran"),smart.screenshotCount.formatted());Divider();reviewRow(language.text("Estimated size","Taille estimée"),screenshotSize);Divider();reviewRow(language.text("Source","Source"),language.text("Apple Photos","Photos Apple"))}.padding(.horizontal,18).background(Color(uiColor:.secondarySystemGroupedBackground),in:RoundedRectangle(cornerRadius:20));Label(language.text("After you confirm here, Apple will still show its own system deletion confirmation.","Après votre confirmation ici, Apple affichera encore sa confirmation système de suppression."),systemImage:"iphone").font(.footnote).foregroundStyle(.secondary);Spacer();Button(role:.destructive){showScreenshotDelete=false;Task{do{try await smart.deleteScreenshots()}catch{cleanupError=error.localizedDescription}}}label:{Label(language.text("Confirm deletion","Confirmer la suppression"),systemImage:"trash.fill").fontWeight(.bold).frame(maxWidth:.infinity).frame(height:48)}.buttonStyle(.borderedProminent).tint(.red);Button(language.text("Cancel","Annuler")){showScreenshotDelete=false}.frame(maxWidth:.infinity)}.padding(24).navigationTitle(language.text("Review","Récapitulatif")).navigationBarTitleDisplayMode(.inline)}}

    private var premiumProtectedCleanupReview: some View { NavigationStack{VStack(alignment:.leading,spacing:22){Image(systemName:"iphone.slash").font(.system(size:44)).foregroundStyle(.green);Text(language.text("Free local space?","Libérer l’espace local ?")).font(.largeTitle.bold());Text(language.text("Only originals already protected by Libérons will be selected for removal from this iPhone.","Seuls les originaux déjà protégés par Libérons seront sélectionnés pour être retirés de cet iPhone.")).foregroundStyle(.secondary);VStack(spacing:0){reviewRow(language.text("Protected originals","Originaux protégés"),protectedStillOnDevice.count.formatted());Divider();reviewRow(language.text("Cloud copy","Copie cloud"),language.text("Protected","Protégée"));Divider();reviewRow(language.text("Action","Action"),language.text("Remove local originals","Retirer les originaux locaux"))}.padding(.horizontal,18).background(Color(uiColor:.secondarySystemGroupedBackground),in:RoundedRectangle(cornerRadius:20));Label(language.text("Apple Photos will ask for final system confirmation before deleting anything.","Photos Apple demandera une confirmation système finale avant toute suppression."),systemImage:"checkmark.shield.fill").font(.footnote).foregroundStyle(.secondary);Spacer();Button(role:.destructive){showPostBackupCleanup=false;Task{await removeProtectedBatchFromDevice()}}label:{Label(language.text("Confirm and free space","Confirmer et libérer l’espace"),systemImage:"trash.fill").fontWeight(.bold).frame(maxWidth:.infinity).frame(height:48)}.buttonStyle(.borderedProminent).tint(.red).disabled(deletingProtectedBatch);Button(language.text("Keep on iPhone","Garder sur l’iPhone")){showPostBackupCleanup=false}.frame(maxWidth:.infinity)}.padding(24).navigationTitle(language.text("Review","Récapitulatif")).navigationBarTitleDisplayMode(.inline)}}

    private func smartMetric(value:Int,label:String,icon:String,tint:Color)->some View{VStack(alignment:.leading,spacing:5){Image(systemName:icon).foregroundStyle(tint);Text(value.formatted()).font(.title3.bold());Text(label).font(.caption).foregroundStyle(.secondary)}.padding(12).frame(maxWidth:.infinity,alignment:.leading).background(Color(uiColor:.secondarySystemGroupedBackground),in:RoundedRectangle(cornerRadius:16))}
    private func reviewRow(_ title:String,_ value:String)->some View{HStack{Text(title);Spacer();Text(value).fontWeight(.semibold).multilineTextAlignment(.trailing)}.padding(.vertical,15)}
    @MainActor private func removeProtectedBatchFromDevice()async{let assets=protectedStillOnDevice;guard !assets.isEmpty else{backup.clearPostBackupOffer();return};deletingProtectedBatch=true;cleanupError=nil;do{try await PHPhotoLibrary.shared().performChanges{PHAssetChangeRequest.deleteAssets(assets as NSArray)};deletingProtectedBatch=false;backup.clearPostBackupOffer()}catch{deletingProtectedBatch=false;let ns=error as NSError;if ns.domain=="PHPhotosErrorDomain" && ns.code==3072{cleanupError=nil}else{cleanupError=language.text("Unable to remove these originals right now.","Impossible de retirer ces originaux pour le moment.")}}}
}
